INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload) VALUES('core-2026-09-v3','sentence-structure','e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4','{"slug":"sentence-structure","title":"Sentence structure and word classes","level":"A1","order":1,"summary":"Start with the building blocks: subjects, verbs, objects, complements and complete clauses.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["Find the subject and the verb","Objects and complements","Word class depends on its job","A complete written sentence"],"rules":[{"title":"Find the subject and the verb","explanation":"A clause normally contains a **subject** and a **verb phrase**. The subject tells us who or what the clause is about. The verb expresses an action, event or state. In a simple statement, the subject usually comes before the verb. A subject can contain several words.","pattern":"**The new guide** **explains** the route.","commonMistakes":["The first noun you see is not always the subject: in On Monday, the guide arrives, Monday belongs to a time phrase."],"examples":["In “The assistant prepares the visitor guide carefully”, which words are the subject? → **The assistant**","In “The assistant restores the old portrait carefully”, which words are the subject? → **The assistant**"],"skill":"form"},{"title":"Objects and complements","explanation":"A transitive verb can take an **object**, the person or thing affected or involved. After a linking verb such as be or seem, a **complement** describes or identifies the subject instead. Compare She paints the door with The door is blue. Blue describes the door; it is not a thing receiving an action.","pattern":"She opens **the door**. / The door is **heavy**.","commonMistakes":["Some verbs need no object: the baby sleeps. Do not force every sentence into subject–verb–object."],"examples":["In “The assistant prepares the visitor guide carefully”, which word is the main verb? → **prepares**","In “The assistant restores the old portrait carefully”, which word is the main verb? → **restores**"],"skill":"meaning"},{"title":"Word class depends on its job","explanation":"A noun names something, an adjective describes a noun, and an adverb can modify a verb, adjective or clause. The same spelling may have different jobs: a clean room uses clean as an adjective; clean the room uses it as a verb. Identify the word in its sentence.","pattern":"They **carefully** open the **heavy** door.","commonMistakes":["An -ly ending is only a clue: friendly is usually an adjective, and fast can be an adjective or adverb."],"examples":["In “The assistant prepares the visitor guide”, which phrase is the object? → **the visitor guide**","In “The assistant restores the old portrait”, which phrase is the object? → **the old portrait**"],"skill":"contrast"},{"title":"A complete written sentence","explanation":"A written sentence needs a complete main clause and suitable final punctuation. A dependent clause introduced by because or although usually needs a main clause beside it. Commands often leave the subject you unspoken, so Open the door is complete.","pattern":"**Because it was cold, we closed the window.**","commonMistakes":["Because it was cold alone is a fragment in ordinary formal prose, though fragments have purposeful uses in conversation and creative writing."],"examples":["Complete the main clause after a reason: “Because there is time, **we prepare** the visitor guide.”","Complete the main clause after a reason: “Because there is time, **we restore** the old portrait.”"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["dfe-grammar","bc-verbs-reference"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"quizItems":[{"id":"b753d69c-63db-56c6-a0cb-6829be52c6ed","topicSlug":"sentence-structure","level":"A1","prompt":"In “The assistant prepares the visitor guide carefully”, which words are the subject?","choices":[{"id":"A","text":"The assistant"},{"id":"B","text":"prepares"},{"id":"C","text":"the visitor guide"},{"id":"D","text":"carefully"}],"answerId":"A","hint":"Find who or what performs the action, then separate it from the action itself.","explanation":"**The assistant** is the subject: it tells us who performs the action.","keywords":["subject-identification"],"skill":"subject-identification","contextKey":"sentence-structure-1","fingerprint":"37137aec504f5e8e117d7fd0eae5e6dd2f4d0060a6c94e9bb506cd13061b2adc","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["dfe-grammar"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Find who or what performs the action, then separate it from the action itself.","**The assistant** is the subject: it tells us who performs the action.","Choose **The assistant**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"**The assistant** is the subject: it tells us who performs the action.","B":"This is the verb, which expresses the action.","C":"This is the object involved in the action.","D":"This adverb describes how the action is performed."}}},{"id":"eb3fcbca-eb13-5054-a837-29f3faef7c11","topicSlug":"sentence-structure","level":"A1","prompt":"In “The assistant prepares the visitor guide carefully”, which word is the main verb?","choices":[{"id":"A","text":"prepares"},{"id":"B","text":"assistant"},{"id":"C","text":"carefully"},{"id":"D","text":"the visitor guide"}],"answerId":"A","hint":"Look for the word that expresses the action.","explanation":"**prepares** expresses the action and agrees with the singular subject.","keywords":["verb-identification"],"skill":"verb-identification","contextKey":"sentence-structure-1","fingerprint":"99dd214d703a246f7e7fcadd34013397fff561e031ed1cbd262f7ef30fd2389e","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["dfe-grammar"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Look for the word that expresses the action.","**prepares** expresses the action and agrees with the singular subject.","Choose **prepares**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"**prepares** expresses the action and agrees with the singular subject.","B":"Assistant is a noun within the subject phrase.","C":"Carefully modifies the verb; it is an adverb.","D":"This noun phrase is the object, not the verb."}}},{"id":"f01f9810-196f-5b16-a16e-048f1015539f","topicSlug":"sentence-structure","level":"A1","prompt":"In “The assistant prepares the visitor guide”, which phrase is the object?","choices":[{"id":"A","text":"the visitor guide"},{"id":"B","text":"The assistant"},{"id":"C","text":"prepares"},{"id":"D","text":"There is no object"}],"answerId":"A","hint":"Ask the verb’s question: the assistant does this to or with **what**?","explanation":"**the visitor guide** answers what the assistant prepares; it is the object of the transitive verb.","keywords":["object-identification"],"skill":"object-identification","contextKey":"sentence-structure-1","fingerprint":"20f7b8ecb7d7729288c33a91eb8b1799c9f84e9a7d50dc1f4487af08a93266a2","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["dfe-grammar"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Ask the verb’s question: the assistant does this to or with **what**?","**the visitor guide** answers what the assistant prepares; it is the object of the transitive verb.","Choose **the visitor guide**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"**the visitor guide** answers what the assistant prepares; it is the object of the transitive verb.","B":"This is the subject performing the action.","C":"This is the verb, not its object.","D":"This transitive clause names the thing involved in the action."}}},{"id":"36ac3071-0829-545b-af73-4aa48a035b53","topicSlug":"sentence-structure","level":"A1","prompt":"Complete the main clause after a reason: “Because there is time, ____ the visitor guide.”","choices":[{"id":"A","text":"to prepare"},{"id":"B","text":"prepareing"},{"id":"C","text":"our"},{"id":"D","text":"we prepare"}],"answerId":"D","hint":"Because introduces a dependent reason clause. The rest still needs a **main clause**.","explanation":"**We prepare** supplies the subject and finite verb for the main clause.","keywords":["clause-completion"],"skill":"clause-completion","contextKey":"sentence-structure-1","fingerprint":"55d15fdfc5165974b389d2f8ca54f85f964f596b2b385300d6c09ac0a5cab2b8","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["dfe-grammar"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Because introduces a dependent reason clause. The rest still needs a **main clause**.","**We prepare** supplies the subject and finite verb for the main clause.","Choose **we prepare**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"A to-infinitive does not supply a finite main clause here.","B":"This form does not supply a subject and finite verb.","C":"A possessive determiner cannot form the missing clause.","D":"**We prepare** supplies the subject and finite verb for the main clause."}}},{"id":"d752f06f-2894-5218-a950-4e5ad1a0c513","topicSlug":"sentence-structure","level":"A1","prompt":"In “The assistant restores the old portrait carefully”, which words are the subject?","choices":[{"id":"A","text":"restores"},{"id":"B","text":"the old portrait"},{"id":"C","text":"carefully"},{"id":"D","text":"The assistant"}],"answerId":"D","hint":"Find who or what performs the action, then separate it from the action itself.","explanation":"**The assistant** is the subject: it tells us who performs the action.","keywords":["subject-identification"],"skill":"subject-identification","contextKey":"sentence-structure-2","fingerprint":"c97f9ad75f1cdf86fd5c9a4f417f0097ec889cb6db3834ba264f8c34f6a0189c","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["dfe-grammar"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Find who or what performs the action, then separate it from the action itself.","**The assistant** is the subject: it tells us who performs the action.","Choose **The assistant**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"This is the verb, which expresses the action.","B":"This is the object involved in the action.","C":"This adverb describes how the action is performed.","D":"**The assistant** is the subject: it tells us who performs the action."}}},{"id":"e2f12ab9-5aa0-58b5-a562-7a28ff48c968","topicSlug":"sentence-structure","level":"A1","prompt":"In “The assistant restores the old portrait carefully”, which word is the main verb?","choices":[{"id":"A","text":"carefully"},{"id":"B","text":"the old portrait"},{"id":"C","text":"restores"},{"id":"D","text":"assistant"}],"answerId":"C","hint":"Look for the word that expresses the action.","explanation":"**restores** expresses the action and agrees with the singular subject.","keywords":["verb-identification"],"skill":"verb-identification","contextKey":"sentence-structure-2","fingerprint":"3e42c5a67fe4d0abcc31519b90e5a03a945abf05e4b34b863b41bfd1fffc18a2","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["dfe-grammar"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Look for the word that expresses the action.","**restores** expresses the action and agrees with the singular subject.","Choose **restores**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Carefully modifies the verb; it is an adverb.","B":"This noun phrase is the object, not the verb.","C":"**restores** expresses the action and agrees with the singular subject.","D":"Assistant is a noun within the subject phrase."}}},{"id":"0d654784-8267-5b03-a510-632469085fdc","topicSlug":"sentence-structure","level":"A1","prompt":"In “The assistant restores the old portrait”, which phrase is the object?","choices":[{"id":"A","text":"The assistant"},{"id":"B","text":"restores"},{"id":"C","text":"There is no object"},{"id":"D","text":"the old portrait"}],"answerId":"D","hint":"Ask the verb’s question: the assistant does this to or with **what**?","explanation":"**the old portrait** answers what the assistant restores; it is the object of the transitive verb.","keywords":["object-identification"],"skill":"object-identification","contextKey":"sentence-structure-2","fingerprint":"8e57833448b44a4a7cb3abe0f3e68c4febca2a906c8ef806ba5618e3f2525da2","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["dfe-grammar"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Ask the verb’s question: the assistant does this to or with **what**?","**the old portrait** answers what the assistant restores; it is the object of the transitive verb.","Choose **the old portrait**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"This is the subject performing the action.","B":"This is the verb, not its object.","C":"This transitive clause names the thing involved in the action.","D":"**the old portrait** answers what the assistant restores; it is the object of the transitive verb."}}},{"id":"16d77e2d-bf5f-574d-afdd-94b7ba6781ac","topicSlug":"sentence-structure","level":"A1","prompt":"Complete the main clause after a reason: “Because there is time, ____ the old portrait.”","choices":[{"id":"A","text":"we restore"},{"id":"B","text":"to restore"},{"id":"C","text":"restoreing"},{"id":"D","text":"our"}],"answerId":"A","hint":"Because introduces a dependent reason clause. The rest still needs a **main clause**.","explanation":"**We restore** supplies the subject and finite verb for the main clause.","keywords":["clause-completion"],"skill":"clause-completion","contextKey":"sentence-structure-2","fingerprint":"c1f1205b16f0e21568d0d537cd0bb821cf9beec493ee409766c7846b66d983c0","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["dfe-grammar"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Because introduces a dependent reason clause. The rest still needs a **main clause**.","**We restore** supplies the subject and finite verb for the main clause.","Choose **we restore**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"**We restore** supplies the subject and finite verb for the main clause.","B":"A to-infinitive does not supply a finite main clause here.","C":"This form does not supply a subject and finite verb.","D":"A possessive determiner cannot form the missing clause."}}},{"id":"112fd590-1e80-54dd-a3f4-ff21a1cfde09","topicSlug":"sentence-structure","level":"A1","prompt":"In “The assistant measures the garden fence carefully”, which words are the subject?","choices":[{"id":"A","text":"the garden fence"},{"id":"B","text":"carefully"},{"id":"C","text":"The assistant"},{"id":"D","text":"measures"}],"answerId":"C","hint":"Find who or what performs the action, then separate it from the action itself.","explanation":"**The assistant** is the subject: it tells us who performs the action.","keywords":["subject-identification"],"skill":"subject-identification","contextKey":"sentence-structure-3","fingerprint":"2e21260eba19647138b64109315475969ed5cfd05aaefcacb571dad457282d12","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["dfe-grammar"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Find who or what performs the action, then separate it from the action itself.","**The assistant** is the subject: it tells us who performs the action.","Choose **The assistant**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"This is the object involved in the action.","B":"This adverb describes how the action is performed.","C":"**The assistant** is the subject: it tells us who performs the action.","D":"This is the verb, which expresses the action."}}},{"id":"db6cc9b9-df29-5405-abfe-c2181e9b7b00","topicSlug":"sentence-structure","level":"A1","prompt":"In “The assistant measures the garden fence carefully”, which word is the main verb?","choices":[{"id":"A","text":"carefully"},{"id":"B","text":"the garden fence"},{"id":"C","text":"measures"},{"id":"D","text":"assistant"}],"answerId":"C","hint":"Look for the word that expresses the action.","explanation":"**measures** expresses the action and agrees with the singular subject.","keywords":["verb-identification"],"skill":"verb-identification","contextKey":"sentence-structure-3","fingerprint":"abe392a72d084aa37930a89079c807e3671fbc4c81d832cd218022a49fcd927a","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["dfe-grammar"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Look for the word that expresses the action.","**measures** expresses the action and agrees with the singular subject.","Choose **measures**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Carefully modifies the verb; it is an adverb.","B":"This noun phrase is the object, not the verb.","C":"**measures** expresses the action and agrees with the singular subject.","D":"Assistant is a noun within the subject phrase."}}},{"id":"c99f85ce-79a5-50a7-ad53-3595f3471008","topicSlug":"sentence-structure","level":"A1","prompt":"In “The assistant measures the garden fence”, which phrase is the object?","choices":[{"id":"A","text":"The assistant"},{"id":"B","text":"measures"},{"id":"C","text":"There is no object"},{"id":"D","text":"the garden fence"}],"answerId":"D","hint":"Ask the verb’s question: the assistant does this to or with **what**?","explanation":"**the garden fence** answers what the assistant measures; it is the object of the transitive verb.","keywords":["object-identification"],"skill":"object-identification","contextKey":"sentence-structure-3","fingerprint":"f2df32a3db1ea3920041297347f807cb09f8dbbba1255ffdc0652f55182391cc","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["dfe-grammar"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Ask the verb’s question: the assistant does this to or with **what**?","**the garden fence** answers what the assistant measures; it is the object of the transitive verb.","Choose **the garden fence**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"This is the subject performing the action.","B":"This is the verb, not its object.","C":"This transitive clause names the thing involved in the action.","D":"**the garden fence** answers what the assistant measures; it is the object of the transitive verb."}}},{"id":"f52d45fd-edeb-5572-a1f3-6eb9be1912be","topicSlug":"sentence-structure","level":"A1","prompt":"Complete the main clause after a reason: “Because there is time, ____ the garden fence.”","choices":[{"id":"A","text":"we measure"},{"id":"B","text":"to measure"},{"id":"C","text":"measureing"},{"id":"D","text":"our"}],"answerId":"A","hint":"Because introduces a dependent reason clause. The rest still needs a **main clause**.","explanation":"**We measure** supplies the subject and finite verb for the main clause.","keywords":["clause-completion"],"skill":"clause-completion","contextKey":"sentence-structure-3","fingerprint":"e480bfe2ef4fe9b732cb5d90398c7a741aae2875390bf407efe8ebd0ef4d8d4d","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["dfe-grammar"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Because introduces a dependent reason clause. The rest still needs a **main clause**.","**We measure** supplies the subject and finite verb for the main clause.","Choose **we measure**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"**We measure** supplies the subject and finite verb for the main clause.","B":"A to-infinitive does not supply a finite main clause here.","C":"This form does not supply a subject and finite verb.","D":"A possessive determiner cannot form the missing clause."}}},{"id":"fbb4cdfe-3631-50a9-a708-98ff6cc89233","topicSlug":"sentence-structure","level":"A1","prompt":"In “The assistant translates the travel leaflet carefully”, which words are the subject?","choices":[{"id":"A","text":"carefully"},{"id":"B","text":"The assistant"},{"id":"C","text":"translates"},{"id":"D","text":"the travel leaflet"}],"answerId":"B","hint":"Find who or what performs the action, then separate it from the action itself.","explanation":"**The assistant** is the subject: it tells us who performs the action.","keywords":["subject-identification"],"skill":"subject-identification","contextKey":"sentence-structure-4","fingerprint":"16828b48868b0f70e3a90ccb36255700a30b698d815e6b5c73046291aead6376","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["dfe-grammar"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Find who or what performs the action, then separate it from the action itself.","**The assistant** is the subject: it tells us who performs the action.","Choose **The assistant**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"This adverb describes how the action is performed.","B":"**The assistant** is the subject: it tells us who performs the action.","C":"This is the verb, which expresses the action.","D":"This is the object involved in the action."}}},{"id":"13377b2b-218b-579d-a0e1-3d0b20dd8239","topicSlug":"sentence-structure","level":"A1","prompt":"In “The assistant translates the travel leaflet carefully”, which word is the main verb?","choices":[{"id":"A","text":"carefully"},{"id":"B","text":"the travel leaflet"},{"id":"C","text":"translates"},{"id":"D","text":"assistant"}],"answerId":"C","hint":"Look for the word that expresses the action.","explanation":"**translates** expresses the action and agrees with the singular subject.","keywords":["verb-identification"],"skill":"verb-identification","contextKey":"sentence-structure-4","fingerprint":"81955ac4d671768d68b881f130d641696d3f79ab745be431167cf0603d04b05f","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["dfe-grammar"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Look for the word that expresses the action.","**translates** expresses the action and agrees with the singular subject.","Choose **translates**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Carefully modifies the verb; it is an adverb.","B":"This noun phrase is the object, not the verb.","C":"**translates** expresses the action and agrees with the singular subject.","D":"Assistant is a noun within the su